// Validate image input
const body = $input.first().json.body || $input.first().json;

const imageBase64 = body.image_base64 || body.image || null;
const analysisType = body.analysis_type || 'disease_detection'; // 'disease_detection' | 'bwd_analysis' | 'both'
const sessionId = body.session_id || `cv_${Date.now()}`;

// Validate base64 image
if (!imageBase64) {
  throw new Error('Field image_base64 wajib disertakan');
}

// Check image size (max 10MB base64 ≈ 7.5MB original)
const sizeBytes = Math.ceil(imageBase64.length * 0.75);
if (sizeBytes > 10 * 1024 * 1024) {
  throw new Error('Ukuran gambar terlalu besar. Maksimum 10MB.');
}

// Detect image format from base64 header
let imageFormat = 'jpeg';
if (imageBase64.startsWith('/9j/')) imageFormat = 'jpeg';
else if (imageBase64.startsWith('iVBOR')) imageFormat = 'png';
else if (imageBase64.startsWith('R0lG')) imageFormat = 'gif';

return [{
  json: {
    image_base64: imageBase64,
    image_format: imageFormat,
    image_size_bytes: sizeBytes,
    analysis_type: analysisType,
    session_id: sessionId,
    request_id: `cv_${Date.now()}_${Math.random().toString(36).substr(2,6)}`,
    start_time: Date.now()
  }
}];

// Parse and combine results from Roboflow + BWD
const items = $input.all();
const validatorData = $('✅ Image Validator').item.json;

// Parse Roboflow result
let roboflowResult = {};
let bwdResult = {};

// Try to get results from both branches
for (const item of items) {
  if (item.json.predictions !== undefined) {
    // Roboflow format
    roboflowResult = {
      predictions: item.json.predictions || [],
      image: item.json.image || {},
      total_detections: (item.json.predictions || []).length
    };
  } else if (item.json.bwd_score !== undefined || item.json.green_ratio !== undefined) {
    // BWD format
    bwdResult = item.json;
  }
}

// Calculate summary
const diseases = (roboflowResult.predictions || []).map(p => ({
  class: p.class,
  confidence: Math.round(p.confidence * 100),
  bbox: {x: p.x, y: p.y, width: p.width, height: p.height}
}));

const avgConfidence = diseases.length > 0
  ? diseases.reduce((sum, d) => sum + d.confidence, 0) / diseases.length
  : 0;

return [{
  json: {
    ...validatorData,
    roboflow_detections: roboflowResult,
    bwd_analysis: bwdResult,
    diseases_found: diseases,
    disease_count: diseases.length,
    avg_confidence: Math.round(avgConfidence),
    analysis_complete: true
  }
}];

