// Build final CV analysis report
const cvData = $('🗂️ Parse CV Results').item.json;
const geminiResponse = $input.first().json;

const aiInterpretation = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text
  || 'Tidak dapat menghasilkan interpretasi AI saat ini.';

const processingTime = Date.now() - cvData.start_time;

return [{
  json: {
    success: true,
    request_id: cvData.request_id,
    session_id: cvData.session_id,
    analysis_type: cvData.analysis_type,
    image_info: {
      format: cvData.image_format,
      size_bytes: cvData.image_size_bytes
    },
    detections: {
      total_diseases_found: cvData.disease_count,
      diseases: cvData.diseases_found,
      avg_confidence_pct: cvData.avg_confidence
    },
    bwd_analysis: cvData.bwd_analysis,
    ai_diagnosis: aiInterpretation,
    severity: cvData.disease_count === 0 ? 'Sehat' :
              cvData.avg_confidence < 50 ? 'Ringan' :
              cvData.avg_confidence < 75 ? 'Sedang' : 'Berat',
    processing_time_ms: processingTime,
    metadata: {
      engine: 'agrisensa-cv-v2',
      models: ['roboflow-detect-classify', 'bwd-cv-model', 'gemini-2.0-flash'],
      workflow: 'WF-03',
      timestamp: new Date().toISOString()
    }
  }
}];
